package com.jnapanam.sportszone.content.model;
import com.jnapanam.sportszone.catalog.model.*;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="public_events")
public class PublicEvent {
 @Id private UUID id; @Column(nullable=false,unique=true,length=100) private String slug; @Column(nullable=false,length=180) private String title; @Column(name="title_kn",length=180) private String titleKn;
 @Column(nullable=false,columnDefinition="TEXT") private String description; @Column(name="description_kn",columnDefinition="TEXT") private String descriptionKn; @Enumerated(EnumType.STRING) @Column(name="event_type",nullable=false,length=30) private EventType eventType;
 @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="sport_id") private Sport sport; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="facility_id") private Facility facility;
 @Column(name="starts_at",nullable=false) private Instant startsAt; @Column(name="ends_at",nullable=false) private Instant endsAt; @Column(name="registration_url",length=500) private String registrationUrl; @Column(name="image_url",length=500) private String imageUrl; private Integer capacity;
 @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ContentStatus status; @Column(nullable=false) private boolean featured; @Column(name="display_order",nullable=false) private int displayOrder; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected PublicEvent(){}
 public PublicEvent(String slug,String title,String titleKn,String desc,String descKn,EventType type,Sport sport,Facility facility,Instant start,Instant end,String registration,String image,Integer capacity,boolean featured,int order){id=UUID.randomUUID();this.slug=slug.trim().toLowerCase(Locale.ROOT);update(title,titleKn,desc,descKn,type,sport,facility,start,end,registration,image,capacity,featured,order);status=ContentStatus.DRAFT;createdAt=Instant.now();updatedAt=createdAt;}
 public void update(String title,String titleKn,String desc,String descKn,EventType type,Sport sport,Facility facility,Instant start,Instant end,String registration,String image,Integer capacity,boolean featured,int order){this.title=title.trim();this.titleKn=clean(titleKn);description=desc.trim();descriptionKn=clean(descKn);eventType=type;this.sport=sport;this.facility=facility;startsAt=start;endsAt=end;registrationUrl=clean(registration);imageUrl=clean(image);this.capacity=capacity;this.featured=featured;displayOrder=order;updatedAt=Instant.now();}
 public void status(ContentStatus s){status=s;updatedAt=Instant.now();}
 public UUID getId(){return id;} public String getSlug(){return slug;} public String getTitle(){return title;} public String getTitleKn(){return titleKn;} public String getDescription(){return description;} public String getDescriptionKn(){return descriptionKn;} public EventType getEventType(){return eventType;} public Sport getSport(){return sport;} public Facility getFacility(){return facility;} public Instant getStartsAt(){return startsAt;} public Instant getEndsAt(){return endsAt;} public String getRegistrationUrl(){return registrationUrl;} public String getImageUrl(){return imageUrl;} public Integer getCapacity(){return capacity;} public ContentStatus getStatus(){return status;} public boolean isFeatured(){return featured;} public int getDisplayOrder(){return displayOrder;}
 private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}
}
